]
N = 4

@lru_cache(maxsize=None)
def solve(i, j):
    if i == N - 1 and j == N - 1:
        return (grid[i][j], 1)
    best_score = -1
    best_count = 10**9
    if i + 1 < N:
        s, c = solve(i + 1, j)
        if s > best_score or (s == best_score and c < best_count):
            best_score = s
            best_count = c
    if j + 1 < N:
        s, c = solve(i, j + 1)
        if s > best_score or (s == best_score and c < best_count):
            best_score = s
            best_count = c
    return (best_score + grid[i][j], best_count + 1)

