def to_base4(n):
    if n == 0:
        return "0"
    digits = []
    while n > 0:
        digits.append(n % 4)
        n //= 4
    digits.reverse()
    result = ""
    for d in digits:
        if d < 10:
            result += str(d)
        else:
            result += chr(ord('A') + d - 10)
    return result

