from functools import lru_cache

CLOSED = {3, 6}
MAXF = 7

@lru_cache(maxsize=None)
def count_paths(f):
    if f == MAXF:
        return 1
    total = 0
    for step in (1, 2):
        nxt = f + step
        if nxt <= MAXF and nxt not in CLOSED:
            total += count_paths(nxt)
    return total

def find_best(f, path):
    if f == MAXF:
        return list(path)
    best = None
    for step in (1, 2):
        nxt = f + step
        if nxt <= MAXF and nxt not in CLOSED:
            cand = find_best(nxt, path + [nxt])
            if best is None:
                best = cand
            else:
                if len(cand) < len(best):
                    best = cand
                elif len(cand) == len(best) and cand < best:
                    best = cand
    return best

